<?php
require_once __DIR__.'/../../includes/layout.php';require_role(['Super Admin']);check_csrf();$error='';
if($_SERVER['REQUEST_METHOD']==='POST')try {
    $id=(int)($_POST['id']??0);$year=(int)($_POST['year_id']??0);$course=(int)($_POST['course_id']??0)?:null;$office=(int)($_POST['office_id']??0);$title=trim((string)($_POST['title']??''));$instructions=trim((string)($_POST['instructions']??''));
    if(strlen($title)<3||strlen($title)>160||strlen($instructions)>1000||!scalar('SELECT COUNT(*) FROM school_years WHERE id=?',[$year])||($course&&!scalar('SELECT COUNT(*) FROM courses WHERE id=? AND is_offered=1',[$course]))||!scalar('SELECT COUNT(*) FROM campus_offices WHERE id=?',[$office]))throw new InvalidArgumentException('Choose a school year, course, and office. Titles need 3–160 characters; instructions allow 1000.');
    if($id&&!scalar('SELECT COUNT(*) FROM enrollment_requirements WHERE id=?',[$id]))throw new InvalidArgumentException('This requirement no longer exists.');
    $values=[$year,$course,$office,$title,$instructions,isset($_POST['required'])?1:0,isset($_POST['active'])?1:0];
    if($id)db()->prepare('UPDATE enrollment_requirements SET year_id=?,course_id=?,office_id=?,title=?,instructions=?,required=?,active=? WHERE id=?')->execute([...$values,$id]);else db()->prepare('INSERT INTO enrollment_requirements(year_id,course_id,office_id,title,instructions,required,active) VALUES(?,?,?,?,?,?,?)')->execute($values);
    log_activity(current_user()['id'],'Enrollment requirement configured','Existing checklist snapshots preserved.');set_flash('success','Requirement saved for new checklists. Existing student checklists are unchanged.');redirect('enrollment_requirements.php');
}catch(InvalidArgumentException $e){$error=$e->getMessage();}
$requirements=rows('SELECT * FROM enrollment_requirements ORDER BY year_id DESC,id');$years=option_list('school_years','name');$courses=option_list('courses','name');$offices=option_list('campus_offices','name');render_header('Enrollment requirements'); ?>
<div class="page-title"><div><span class="eyebrow">SUPER ADMIN</span><h1>Enrollment requirements</h1><p>Publish the school's real requirements by school year and course. No official requirements are assumed or seeded.</p></div><a class="btn btn-outline-primary" href="../shared/enrollment.php">Review checklists</a></div><?php if($error): ?><div class="alert alert-danger" role="alert"><?= e($error) ?></div><?php endif; ?>
<?php foreach([...$requirements,['id'=>0,'year_id'=>0,'course_id'=>null,'office_id'=>0,'title'=>'','instructions'=>'','required'=>1,'active'=>1]] as $r): ?><section class="panel"><h2><?= $r['id']?e($r['title']):'Add a school requirement' ?></h2><form method="post" class="campus-form"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><label for="enrollment-year-<?= (int)$r['id'] ?>">School year</label><select id="enrollment-year-<?= (int)$r['id'] ?>" name="year_id" class="form-select" required><option value="">Choose school year</option><?php foreach($years as $year): ?><option value="<?= (int)$year['id'] ?>" <?= (int)$r['year_id']===(int)$year['id']?'selected':'' ?>><?= e($year['label']) ?></option><?php endforeach; ?></select><label for="enrollment-course-<?= (int)$r['id'] ?>">Course</label><select id="enrollment-course-<?= (int)$r['id'] ?>" name="course_id" class="form-select"><option value="">All courses</option><?php foreach($courses as $c): ?><option value="<?= (int)$c['id'] ?>" <?= (int)$r['course_id']===(int)$c['id']?'selected':'' ?>><?= e($c['label']) ?></option><?php endforeach; ?></select><label for="enrollment-office-<?= (int)$r['id'] ?>">Reviewing office</label><select id="enrollment-office-<?= (int)$r['id'] ?>" name="office_id" class="form-select" required><option value="">Choose office</option><?php foreach($offices as $o): ?><option value="<?= (int)$o['id'] ?>" <?= (int)$r['office_id']===(int)$o['id']?'selected':'' ?>><?= e($o['label']) ?></option><?php endforeach; ?></select><label>Requirement title<input name="title" class="form-control" value="<?= e($r['title']) ?>" minlength="3" maxlength="160" required></label><label>School instructions<textarea name="instructions" class="form-control" maxlength="1000" rows="3"><?= e($r['instructions']) ?></textarea></label><label><input type="checkbox" name="required" <?= $r['required']?'checked':'' ?>> Required</label><label><input type="checkbox" name="active" <?= $r['active']?'checked':'' ?>> Published for new checklists</label><button class="btn btn-primary">Save requirement</button></form></section><?php endforeach;render_footer(); ?>
